mapper.select:
select cb.*, c.name as categoryName, b.name as brandName,b.logo from category_brand cb inner join category c on cb.category_id = c.id inner join brand b on b.id = cb.brand_id where cb.is_deleted = 0
and cb.category_id = #{dto.categoryId}
and cb.brand_id = #{dto.brandId}
order by cb.id desc
